def diheds(cells):
    res=set()
    cur=[list(p) for p in cells]
    for k in range(4):
        for flip in (False,True):
            c2=[[x*- (1 if flip else 1), y] for x,y in cur]
            # rotate 90cw: (x, -y); mirror horizontally within each rot: negate x
            if not flip: c2=[[x,-y] for y,x in cur]
            ys=[q[0] for q in c2]; xs=[q[1] for q in c2]
            res.add(tuple(sorted((y-min(ys), x-min(xs)) for y,x in c2)))
        cur=[[x,-y] for y,x in cur]
    return res
