def solve(gin):
    g=[[0]*10 for _ in range(10)]
    H,W=len(gin),len(gin[0])
    mask=np.array(gin)!=0
    seen=np.zeros(mask.shape,bool); comps=[]
    for i in range(H):
        for j in range(W):
            if mask[i,j] and not seen[i,j]:
                st=[(i,j)]; seen[i,j]=True; c=[]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                comps.append(c)
    groups={}
    for c in comps: groups.setdefault(gin[c[0][0]][c[0][1]],[]).append(c)
    def lcol(cs): return min(min(q[1] for q in c) for c in cs)
    L=min(groups,key=lcol); O=[v for v in groups if v!=L][0]
    Lmax=max(max(q[1] for q in c) for c in groups[L])
    def stack(ccs,X):
        # smaller on top, one empty row gap, largest flush bottom
        order=sorted(ccs,key=len)
        cur=9-(9-max(p[0] for p in order[-1])+1)   # largest flush bottom
        tops={}
        remaining=max(p[0] for p in order[-1])
        # build from bottom upward
        placed_row=order[-1]
        for cc in reversed(order[1:]):
            ys=[q[0] for q in cc]; h=max(ys)-min(ys)+1
            placed_row-=h+1
        for cc in order:
            ys=[q[0] for q in cc]; xs=[q[1] for q in cc]
            h=max(ys)-min(ys)+1; x0=min(xs)
            for y,x in cc:
                r=placed_row+(y-min(ys)); cl=X+x0+(x-min(xs))
                g[r][cl]=gin[y][x]
            placed_row-=h+1
    stack(groups[L],0); stack(groups[O],Lmax+2)
